// Payment 1 = 2013-06-21. Payment m = June 2013 + (m-1) months
function paymentDate(m) {
  let y = 2013, mo = 6;
  for (let p = 1; p < m; p++) {
    mo++;
    if (mo > 12) { mo = 1; y++; }
  }
  return {y, mo};
}
