const P = 300000;
const annual = 0.031;
const n = 180;
const i = annual / 12;
const M = P * (i * Math.pow(1+i, n)) / (Math.pow(1+i, n) - 1);
function balanceAfterK(k) {
  return P * (Math.pow(1+i, n) - Math.pow(1+i, k)) / (Math.pow(1+i, n) - 1);
}
const k = 164; // completed before paying March 2027
